// What a skill shows: its chosen logo ("none" = letters only), else the one its name matches, else null.
export function skillLogoFor(item){
  if (!item) return null;
  const pick = typeof item.logo === 'string' ? item.logo : '';
  if (pick === 'none') return null;
  if (pick && Object.prototype.hasOwnProperty.call(SKILL_LOGOS, pick)) return { slug: pick, ...SKILL_LOGOS[pick] };
  const slug = SKILL_LOGO_ALIASES[String(item.name || '').toLowerCase().replace(/[^a-z0-9]+/g, '')];
  return slug ? { slug, ...SKILL_LOGOS[slug] } : null;
}
export const SKILL_LOGO_LIST = Object.entries(SKILL_LOGOS).map(([slug, v]) => ({ slug, name: v.n, kind: v.k }))
  .sort((a, b) => a.name.localeCompare(b.name));
